    sendCustomerPaymentSetupEmail: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                customer_id: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": {
                    /**
                     * @description Optional text shown at the top of the email. At most
                     *     2000 bytes (UTF-8) after trimming whitespace.
                     */
                    note?: string;
                };
            };
        };
        responses: {
            /** @description Email queued. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description The address the email was sent to. */
                        to: string;
                        subject: string;
                    };
                };
            };
            /** @description Customer not found. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description `email_not_configured`: this server has no SMTP set up. Nothing
             *     was sent and no setup link was created. Like any other call, it
             *     starts the one-minute cooldown.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description `note_too_long` (more than 2000 bytes) or
             *     `missing_email` (the customer has no email).
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description This endpoint was called for this customer less than a minute ago (`cooldown_active`). */
            429: {
                headers: {
                    /** @description Seconds to wait. */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description Stripe is not connected for this mode, or the setup session
             *     could not be created. No email was queued.
             */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description The email could not be queued (`email_enqueue_failed`), or
             *     Stripe refused to create the setup session with a message it
             *     is safe to show (`provider_error`). Retry.
             */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Email sending is not set up on this server (`email_unavailable`). */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
